const text = needText(m, '.iqc Halo dunia')
const file = await apiFile('/api/iqc', { text, time: '09.41' })
await sendImage(conn, m, file, 'Screenshot iPhone dari: ' + text)

const parts = m.args || []
let image = ''
const rest = []
for (const p of parts) { if (p.includes('://')) image = p; else rest.push(p) }
if (!image) image = await resolveImageSource(m)
const file = await apiFile('/api/meme', { image, top: rest[0] || '', bottom: rest[1] || '' })
await sendImage(conn, m, file, 'Meme: ' + (rest.join(' ') || 'tanpa teks'))

const parts = m.args || []
let image = ''
const rest = []
for (const p of parts) { if (p.includes('://')) image = p; else rest.push(p) }
if (!image) image = await resolveImageSource(m)
const file = await apiFile('/api/watermark', { image, text: rest.join(' ') || 'HABI API', position: 'br', opacity: '0.75' })
await sendImage(conn, m, file, 'Watermark: ' + (rest.join(' ') || 'HABI API'))

const text = needText(m, '.brat halo semua')
const file = await apiFile('/api/brat', { text })
await sendImage(conn, m, file, 'Brat: ' + text)

const text = needText(m, '.bratvid halo semua')
const file = await apiFile('/api/bratvid', { text, duration: '2' })
await sendVideo(conn, m, file, 'Brat video: ' + text)

const [name, group] = m.args || []
if (!name) throw new Error('Isi namanya dulu. Contoh: .welcomecard Budi Komunitas Hacker ID')
const file = await apiFile('/api/welcome', { name, group: group || 'Grup WhatsApp', accent: 'green' })
await sendImage(conn, m, file, 'Selamat datang, ' + name + '!')

const image = needUrl(m, '.stikerapi https://contoh.com/foto.jpg')
const file = await apiFile('/api/sticker', { image, format: 'webp' })
await conn.sendMessage(m.chat, { sticker: file, mimetype: 'image/webp' }, { quoted: m.raw })

const q = needText(m, '.ytsearch rizky janaka')
const data = await apiJson('/api/ytsearch', { q, limit: '8' })
if (!data.results || !data.results.length) throw new Error('Tidak ada hasil untuk ' + q)
const list = data.results.map((r, i) =>
  (i + 1) + '. ' + String(r.title).slice(0, 40) + '\n   ' + (r.duration ? duration(r.duration) : '?') +
  ' | ' + (r.uploader || '?') + '\n   ' + r.url
).join('\n')
await sendText(conn, m, 'Hasil untuk ' + q + '\n\n' + list + '\n\nUnduh dengan .ytmp3 atau .ytmp4')

const url = needUrl(m, '.ytinfo https://youtu.be/VIDEO_ID')
const d = await apiJson('/api/ytinfo', { url })
await sendText(conn, m, [
  d.title, '',
  'Durasi  : ' + duration(d.duration),
  'Channel : ' + (d.uploader || '-'),
  'Views   : ' + (d.view_count ? d.view_count.toLocaleString('id-ID') : '-'),
  'Format  : ' + (d.ext || '-'),
  '', d.webpage_url,
].join('\n'))

const id = needText(m, '.ytthumb dQw4w9WgXcQ')
const d = await apiJson('/api/ytthumb', { id })
await sendText(conn, m, 'Thumbnail

HD : ' + d.urls.maxres + '
SD : ' + d.urls.sd + '
HQ : ' + d.urls.hq)

const url = needUrl(m, '.spotify https://open.spotify.com/track/ID')
const d = await apiJson('/api/spotify', { url })
await sendText(conn, m, [
  d.title, '',
  'Artis : ' + d.artist,
  'Yakin : ' + d.matched.confidence,
  '', d.matched.url,
  '', 'Unduh: .ytmp3 ' + d.matched.url,
].join('\n'))

const url = needUrl(m, '.apiget https://www.tiktok.com/@user/video/ID')
let platform = '-'
try {
  const det = await apiJson('/api/detect', { url })
  platform = det.platform || '-'
} catch { /* abaikan */ }
const d = await apiJson('/api/resolve', { url })
const v = d.media && d.media.video
if (!v || !v.url) throw new Error('Tidak ada video yang bisa diambil dari link itu.')
await sendText(conn, m, [
  String(d.title || '-').slice(0, 45), '',
  'Platform : ' + d.platform,
  'Sumber   : ' + d.source,
  'Ukuran   : ' + bytes(v.size),
  'Resolusi : ' + (v.width || '?') + 'x' + (v.height || '?'),
  '', v.url,
  '', 'Kirim video ini ke chat dengan .apikirim',
].join('\n'))

const url = needUrl(m, '.apikirim https://www.tiktok.com/@user/video/ID')
const d = await apiJson('/api/resolve', { url })
const v = d.media && d.media.video
if (!v || !v.url) throw new Error('Tidak ada video yang bisa diambil dari link itu.')
await conn.sendMessage(m.chat, {
  video: { url: v.url }, mimetype: 'video/mp4',
  caption: String(d.title || 'Media').slice(0, 60),
}, { quoted: m.raw })

const url = needUrl(m, '.detect https://vm.tiktok.com/XXXX/')
const d = await apiJson('/api/detect', { url })
await sendText(conn, m, 'Link itu platformnya: ' + d.platform + '\n\n' + url)

const url = needUrl(m, '.getfile https://contoh.com/file.pdf')
const file = await apiFile('/api/file', { url })
let name = 'habi-file'
try { name = decodeURIComponent(new URL(url).pathname.split('/').pop() || name) } catch { /* abaikan */ }
await sendFile(conn, m, file, name.slice(0, 60))

const text = needText(m, '.humanizer It is important to note that this')
const d = await apiJson('/api/humanizer', { text, mode: 'indo' })
const out = d.text || d.result || d.output || ''
if (!out) throw new Error('API tidak mengembalikan teks.')
await sendText(conn, m, 'Humanizer\n\n' + String(out))

const parts = m.args || []
const codes = ['id', 'en', 'ja', 'ko', 'zh', 'ar', 'ru', 'th', 'ms', 'de', 'fr', 'es', 'pt', 'it', 'nl', 'tr']
let to = 'id'
if (codes.indexOf(String(parts[0] || '').toLowerCase()) !== -1) to = String(parts[0]).toLowerCase()
const text = parts.filter((p) => p.toLowerCase() !== to).join(' ') || needText(m, '.translate en Halo dunia')
const d = await apiJson('/api/translate', { text, to })
const out = d.translated || d.result || d.text || '(kosong)'
await sendText(conn, m, 'Terjemahan (' + to.toUpperCase() + ')\n\n' + String(out))

const url = needUrl(m, '.ocr https://contoh.com/foto.jpg')
const d = await apiJson('/api/ocr', { url })
const t = d.text || d.result || d.ocr || ''
if (!t) throw new Error('Tidak ada teks yang terbaca di gambar itu.')
await sendText(conn, m, 'Hasil OCR\n\n' + String(t).slice(0, 3000))

const url = needUrl(m, '.ssweb https://example.com')
const file = await apiFile('/api/ssweb', { url })
await sendImage(conn, m, file, 'Screenshot ' + url)

const url = needUrl(m, '.webfetch https://example.com')
const d = await apiJson('/api/webfetch', { url })
const t = d.content || d.text || d.result || ''
if (!t) throw new Error('Halamannya kosong atau tidak bisa dibaca.')
await sendText(conn, m, url + '\n\n' + String(t).slice(0, 3000))

const url = needUrl(m, '.removebg https://contoh.com/foto.jpg')
const file = await apiFile('/api/removebg', { url })
await sendImage(conn, m, file, 'Background sudah dihapus')

const q = needText(m, '.phonespec iPhone 15 Pro')
const d = await apiJson('/api/phonespecs', { q })
const s = d.specs || d.data || d
let lines
if (s && typeof s === 'object' && !Array.isArray(s)) {
  lines = Object.keys(s).map((k) => '• ' + k + ' : ' + s[k]).join('\n')
} else {
  lines = String(s)
}
await sendText(conn, m, q + '\n\n' + String(lines).slice(0, 3000))

const args = m.args || []
const a = args[0]
const b = args.slice(1).join(' ')
if (!a || !b) throw new Error('Sebut dua HP. Contoh: .phonecompare iPhone 15 Pro Samsung S23')
const d = await apiJson('/api/phonecompare', { a, b })
await sendText(conn, m, [d.phone1 + '  vs  ' + d.phone2, '', d.url || ''].filter(Boolean).join('\n'))

const q = needText(m, '.lirik Indonesia Raya')
const d = await apiJson('/api/lirik', { q })
const lyric = d.lyrics || d.lirik || d.text || ''
if (!lyric) throw new Error('Lirik ' + q + ' tidak ketemu. Coba judul yang lebih umum.')
await sendText(conn, m, (d.title || q) + (d.artist ? ' - ' + d.artist : '') + '\n\n' + String(lyric).slice(0, 3000))

const text = needText(m, '.ttsapi Halo dunia')
const file = await apiFile('/api/tts', { text })
await sendAudio(conn, m, file, text.slice(0, 60))

const url = needUrl(m, '.pdfcompress https://contoh.com/file.pdf')
const file = await apiFile('/api/pdfcompress', { url })
await sendFile(conn, m, file, 'kecil.pdf', 'application/pdf')
